sql.where:
uv.deleted = 0



    AND uv.village_id = #{reqVO.villageId}


    AND uv.name LIKE CONCAT('%', #{reqVO.name}, '%')


    AND uv.address LIKE CONCAT('%', #{reqVO.address}, '%')


    AND uv.area_code = #{reqVO.areaCode}


    AND uv.responsibility_areas = #{reqVO.responsibilityAreas}


    AND uv.road_cleaning_frequency LIKE CONCAT('%', #{reqVO.roadCleaningFrequency}, '%')


    AND uv.manager_id = #{reqVO.managerId}


    AND uv.operation_status_id = #{reqVO.operationStatusId}




    AND uv.cleaning_rate = #{reqVO.cleaningRate}


    AND uv.problem_rate = #{reqVO.problemRate}


    AND uv.review_pass_rate = #{reqVO.reviewPassRate}


    AND uv.assessment_score = #{reqVO.assessmentScore}



    AND uv.responsibility_area_name LIKE CONCAT('%', #{reqVO.responsibilityAreaName}, '%')


    AND uv.cleaning_standard LIKE CONCAT('%', #{reqVO.cleaningStandard}, '%')


    AND uv.staff_ids LIKE CONCAT('%', #{reqVO.staffIds}, '%')


    AND uv.problem_location LIKE CONCAT('%', #{reqVO.problemLocation}, '%')


    AND uv.problem_desc LIKE CONCAT('%', #{reqVO.problemDesc}, '%')


    AND uv.report_by = #{reqVO.reportBy}




    AND uv.report_time BETWEEN #{reqVO.reportTime[0]} AND #{reqVO.reportTime[1]}



    AND uv.problem_photo_url LIKE CONCAT('%', #{reqVO.problemPhotoUrl}, '%')


    AND uv.dept_id = #{reqVO.deptId}


    AND uv.handle_by = #{reqVO.handleBy}



    AND uv.dispatch_time BETWEEN #{reqVO.dispatchTime[0]} AND #{reqVO.dispatchTime[1]}



    AND uv.handle_status_id = #{reqVO.handleStatusId}


    AND uv.is_timeout = #{reqVO.isTimeout}


    AND uv.handle_desc LIKE CONCAT('%', #{reqVO.handleDesc}, '%')


    AND uv.reform_photo_url LIKE CONCAT('%', #{reqVO.reformPhotoUrl}, '%')


    AND uv.review_by = #{reqVO.reviewBy}



    AND uv.review_time BETWEEN #{reqVO.reviewTime[0]} AND #{reqVO.reviewTime[1]}



    AND uv.review_result_id = #{reqVO.reviewResultId}


    AND uv.review_opinion LIKE CONCAT('%', #{reqVO.reviewOpinion}, '%')




    AND uv.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
